/* ==UserStyle==
@name PCPartPicker Catppuccin
@namespace github.com/catppuccin/userstyles/styles/pcpartpicker
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/pcpartpicker
@version 2026.11.01
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/pcpartpicker/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Apcpartpicker
@description Soothing pastel theme for PCPartPicker
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/lib.less";

@-moz-document domain("pcpartpicker.com") {
  :root {
    &.dark-mode {
      #catppuccin(@darkFlavor);
    }
    &.light-mode {
      #catppuccin(@lightFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    .set-colors(@bg, @border, @text) {
      background-color: @bg;
      border-color: @border;
      color: @text;
    }

    background-color: @base;
    body, .wrapper__pageContent {
      color: @text;
      background-color: @base;
    }
    svg.icon, svg.nav__icon {
      fill: @subtext0 !important;
    }

    a[href]:not(.button) {
      color: @accent;
      &:hover {
        color: lighten(@accent, 5%);
      }
    }

    .list-unstyled li {
      color: @text;
      border-color: @surface0;
    }

    @logo: escape(
