2s1.3-.5 2.2-.5c.7 0 1.3.1 1.9.3.5.2 1 .5 1.4.9.5.4.8 1 1.1 1.7.2.7.4 1.5.4 2.3h-3c0-.4-.1-.7-.1-1s-.2-.6-.3-.8-.3-.4-.6-.5c-.2-.1-.5-.2-.9-.2s-.6.1-.9.2c-.2.1-.4.3-.6.5-.3.5-.5 1.2-.6 2.2s-.1 2.4-.1 4.1c0 1.8 0 3.1.1 4.1s.3 1.7.6 2.2c.1.2.3.4.6.5.2.1.5.2.9.2s.6-.1.9-.2c.2-.1.4-.3.6-.5.1-.3.3-.5.3-.8.1-.3.1-.6.1-1zm10 5-3.1-7.8-1.4 2.9v4.9h-3v-19h3V20l4.1-8.9h3L153 19l4.4 11.1zm5 0v-19h8v2.7h-5v5.4h4.3v2.7h-4.3v5.5h5v2.7zm17.6 0-2.5-7.8h-1.7v7.8h-3v-19h4.8c1.8 0 3 .4 3.7 1.3s1.1 2.3 1.1 4.3c0 1.2-.1 2.2-.4 3s-.9 1.5-1.8 2l2.8 8.4zm-.4-13.3c0-.4 0-.8-.1-1.1-.1-.4-.1-.7-.3-.9q-.15-.45-.6-.6c-.3-.1-.6-.2-1-.2h-1.8v5.8h1.8c.4 0 .7-.1 1-.2.2-.1.4-.4.6-.6s.2-.6.3-.9c0-.6.1-.9.1-1.3M17.6.4l-12.1 7v5L0 9.2v21.6l18.7 10.8v-6.3l4.3 2.5 12.1-7V10.5zm16.3 29.7L23 36.4l-5.5-3.2v6.3L1.2 30.1V11.2l5.5 3.2V8.1l10.9-6.3L34 11.3z"/><path style="fill:@{accent}" d="m15.7 13.3-5.4 3.2 7.3 4.1 5.4-3.1z"/><path class="st1" d="m23 25.9-5.4 3.2v-8.5l5.4-3.1z"/><path d="m17.6 3.9-7.3 4.2 13.6 7.8 7.3-4.2zm7.2 13.6 7.3-4.2v15.8l-7.3 4.2zM3 14.4l12.7 7.3v14.7L3 29.1z" style="fill:@{subtext0}"/></svg>'
    );
    @logoSmall: escape(
      '<svg xmlns="http://www.w3.org/2000/svg" width="36" height="42" viewBox="0 0 36 42" xml:space="preserve"><path d="m17.6.4-12.1 7v5L0 9.2v21.6l18.7 10.8v-6.3l4.3 2.5 12.1-7V10.5zm16.3 29.7L23 36.4l-5.5-3.2v6.3L1.2 30.1V11.2l5.5 3.2V8.1l10.9-6.3L34 11.3z" style="fill:@{text}"/><path style="fill:@{accent}" d="m15.7 13.3-5.4 3.2 7.3 4.1 5.4-3.1z"/><path style="fill:@{accent}" d="m23 25.9-5.4 3.2v-8.5l5.4-3.1z"/><path d="m17.6 3.9-7.3 4.2 13.6 7.8 7.3-4.2zm7.2 13.6 7.3-4.2v15.8l-7.3 4.2zM3 14.4l12.7 7.3v14.7L3 29.1z" style="fill:@{subtext0}"/></svg>'
    );
    @logoText: escape(
      '<svg xmlns="http://www.w3.org/2000/svg" width="127" height="19" viewBox="0 0 127 19" fill="none"><path fill="@{text}" d="M9.167 5.832c0 1.906-.361 3.308-1.084 4.177-.722.898-1.916 1.318-3.555 1.318H2.833v7.122H0V.28h4.528c1.639 0 2.805.449 3.555 1.346q1.084 1.346 1.084 4.206m-2.834 0c0-.925-.139-1.654-.389-2.16-.25-.532-.75-.784-1.527-.784H2.833v5.86h1.584c.75 0 1.277-.253 1.527-.785.25-.505.39-1.234.39-2.131m14.222 7.794a7.1 7.1 0 0 1-.417 2.243c-.25.673-.611 1.234-1.056 1.654a4.4 4.4 0 0 1-1.333.87c-.5.196-1.083.28-1.778.28-.833 0-1.555-.14-2.11-.449-.556-.308-1.029-.673-1.39-1.121a4.8 4.8 0 0 1-.722-1.206 7.5 7.5 0 0 1-.389-1.598 22 22 0 0 1-.167-2.13c-.027-.814-.027-1.74-.027-2.833s0-2.018.027-2.831c.028-.813.084-1.514.167-2.131s.222-1.15.39-1.598c.166-.449.416-.841.721-1.206.361-.449.834-.813 1.39-1.121S15.111 0 15.971 0a5.8 5.8 0 0 1 1.806.28c.5.197.972.477 1.361.87.444.42.806.953 1.028 1.626.222.645.36 1.402.416 2.215h-2.86a11 11 0 0 0-.112-.982 2.2 2.2 0 0 0-.305-.785 1.45 1.45 0 0 0-.528-.476c-.222-.112-.472-.169-.833-.169-.334 0-.612.057-.834.197s-.389.28-.528.504c-.277.449-.472 1.15-.527 2.103a67 67 0 0 0-.111 3.925c0 1.683.027 2.972.11 3.926.056.953.25 1.654.528 2.102.14.197.306.365.528.505s.472.196.833.196q.501 0 .834-.168a1.45 1.45 0 0 0 .528-.476 2.6 2.6 0 0 0 .305-.814c.056-.308.084-.616.111-.98h2.834z"/><path fill="@{accent}" d="M32.111 5.832c0 1.906-.361 3.308-1.083 4.177-.722.898-1.917 1.318-3.556 1.318h-1.694v7.122h-2.833V.28h4.527c1.64 0 2.806.449 3.556 1.346q1.083 1.346 1.083 4.206m-2.833 0c0-.925-.14-1.654-.39-2.16-.25-.532-.75-.784-1.527-.784h-1.583v5.86h1.583c.75 0 1.278-.253 1.528-.785.25-.505.389-1.234.389-2.131M40.5 18.477l-.722-3.617H35.61l-.722 3.617h-3L36.333.28h2.75l4.39 18.197zM37.694 4.682l-1.555 7.626h3.083zm14.223 13.795-2.361-7.458h-1.584v7.458H45.14V.28h4.555c1.667 0 2.834.421 3.556 1.262s1.056 2.215 1.056 4.094c0 1.121-.14 2.074-.417 2.887-.278.813-.833 1.43-1.667 1.879l2.695 8.075zm-.445-12.841c0-.365-.028-.73-.055-1.06