    );

    //==Inputs==//
    // Input
    input:not(.button) {
      background-color: @mantle;
      border-color: @mantle;
      color: @text;
      box-shadow: none;
    }
    .wrapper-formField label {
      color: @text;
    }

    // Select
    select {
      background-color: @mantle;
      color: @text;
      // Down arrow
      @svg: escape(
        '<svg version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" x="0px" y="0px" viewBox="0 0 18 18" enable-background="new 0 0 18 18" xml:space="preserve"><polygon points="9,13.6 2.2,6.8 3.8,5.2 9,10.4 14.2,5.2 15.8,6.8" fill="@{text}"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}") !important;
      box-shadow: none;
    }
    textarea {
      background-color: @mantle;
      box-shadow: none;
    }

    // Buttons (all types)
    .button {
      .set-colors(@accent, @accent, @base);
      svg {
        fill: @base !important;
      }
      &.button--negative {
        .set-colors(@red, @red, @base);
      }
      &.button--success {
        .set-colors(@green, @green, @base);
      }
      &.button--dark {
        .set-colors(@base, @base, @text);
        svg {
          fill: @text !important;
        }
      }

      &:not(.button--disabled):not(:disabled):hover {
        .set-colors(lighten(@accent, 5%), lighten(@accent, 5%), @base);
        &.button--negative {
          .set-colors(lighten(@red, 5%), lighten(@red, 5%), @base);
        }
        &.button--success {
          .set-colors(lighten(@green, 5%), lighten(@green, 5%), @base);
        }
        &.button--dark {
          .set-colors(@mantle, @mantle, @text);
        }
      }
    }

    // Radio
    .radio + label::before {
      border-color: @surface0;
      background-color: @crust;
    }
    .radio:checked + label::before {
      border-color: @accent;
      background-color: @base;
    }

    // Checkbox
    .checkbox + label::before {
      background-color: @crust;
      border-color: transparent;
    }
    .checkbox:checked + label::before {
      background-color: @accent;
      border-color: @accent;
      @svg: escape(
        '<svg viewBox="0 -0.5 25 25" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="m5.5 12.5 4.667 4.5L19.5 8" stroke="@{base}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>'
      );
      background-image: url("data:image/svg+xml,@{svg}") !important;
    }

    // Slider to select a range of values
    .filter_slider--wrapper {
      .ui-slider {
        background-color: @surface0;
      }
      .ui-slider-range, .ui-slider-handle {
        background-color: @accent;
      }
    }
    // Buttons to show more/less info
    .moreless {
      color: @accent !important;
      &:hover {
        color: lighten(@accent, 5%) !important;
      }
      svg {
        fill: @accent !important;
      }
    }
    .collapse-toggle::after, .collapse-toggle::before {
      background-color: @text !important;
    }

    // Switch Toggle
    .toggle + label > .toggle__track {
      background-color: @crust;
      border-color: @crust;
      &::before {
        background-color: @subtext1;
        border-color: @crust;
      }
    }
    .toggle:checked + label > .toggle__track {
      background-color: @accent;
      border-color: @accent;
      &::before {
        background-color: @crust;
        border-color: @accent;
      }
    }

    // === Tables === //
    table, .table {
      td {
        color: @text;
      }
      tr, .tr, .td__component {
        border-color: @surface1;
      }
      th, .th {
        color: @text;
        border-color: @surface2;
      }
      .specLabel {
        color: @subtext0 !important;
      }
      .td__name a, .td__nameWrapper a, .row--forumTitle a {
        color: @text !important;
        &:hover {
          color: @accent !important;
        }
      }
      .row--topicTitle a,
      .td__finalPrice a,
      .td__amazonNote a,
      .td__price a,
      .td__promo a,
      .row--lastPostTimestamp a {
        color: @accent !important;
        &:hover {
          color: lighten(@accent, 5%) !important;
        }
      }
      .td__price--out-of-stock {
        color: @overlay0 !important;
      }
      .td--empty::after {
        background-color: @surface0;
      }
      .th--sortable {
        .sortArrow svg {
          fill: @surface0 !important;
        }
        &:hover {
          border-color: @accent !important;
          .sortArrow svg {
            fill: @accent !important;
          }
        }
      }
      .th--sorted {
        border-color: @accent !important;
        .sortArrow svg {
          fill: @accent !important;
        }
      }
      .td__promoNote span {
        background-color: @yellow !important;
        border-color: @yellow !important;
        color: @base !important;
      }
      .td__image, .td__image a {
        border-color: transparent !important;
      }
      .td__locked svg {
        fill: @subtext0 !important;
        &:hover {
          fill: @accent !important;
        }
      }
      .td__remove svg {
        fill: @subtext0 !important;
        &:hover {
          fill: @red !important;
        }
      }
    }

    // === Popup Windows === //
    .modal__container {
      background-color: @surface0;
      box-shadow: none;

      .modal__close {
        &:hover svg {
          fill: @red !important;
        }
      }
    }

    // === Markdown === //
    .markdown {
      p, h1, h2, h3, h4, h5, h6 {
        color: @text;
      }
      blockquote {
        background-color: fade(@accent, 10%);
        border-color: @accent;
      }
      hr {
        border-color: @surface1;
      }

      table {
        background-color: @surface0;
        border-color: @surface0;
        thead th {
          background-color: @surface2;
        }
      }
    }

    // === Build Cards === //
    .logGroup, .guideGroup {
      background-color: @mantle;
      &:hover h1 {
        color: @accent;
      }
      p {
        color: @text;
      }
      .log__numbers, .guide__numbers {
        border-color: @surface0;
      }
    }

    // === Page Titles === //
    .wrapper__pageTitle {
      color: @text !important;
      background-color: @mantle !important;
      .pageTitle {
        color: @text;
      }
      > section > div {
        color: @subtext0;
      }
      h4 {
        color: @subtext0;
      }
      #tabs a {
        &:not(.active) {
          color: @subtext0;
          &:hover {
            background-color: @surface0;
          }
        }
        &.active {
          background-color: @base;
          color: @text;
        }
      }
      .breadcrumb {
        a {
          color: @subtext0;
          &:hover {
            color: @text;
          }
        }
        li::after {
          box-shadow: inset 0 0 0 2px @surface1;
        }
      }
    }

    // === Header === //
    header {
      .nav__logo--full {
        content: url("data:image/svg+xml,@{logo}");
      }
      .nav__logo--icon {
        content: url("data:image/svg+xml,@{logoSmall}");
      }
      .nav__top, .navLogoOnly {
        background-color: @crust;
      }

      .nav__account .language-selector, .modeSwitch__label {
        color: @text !important;
      }

      .navDesktop {
        background-color: @crust;
        a {
          color: @text !important;
        }
        a:hover, select:hover {
          color: @accent !important;
          svg {
            fill: @accent !important;
          }
        }

        .nav__account a {
          border-color: @surface0;
        }
        .flag-icon {
          border-color: @text;
        }
      }
      .nav__bottom {
        background-color: @crust;
        border-color: @base;

        .nav__categories > li > a {
          color: @subtext0 !important;
          border-color: @base;

          &:hover {
            background-color: @mantle;
            svg {
              fill: @accent;
            }
          }
          &.nav__categories--active {
            background-color: @mantle;
            color: @accent !important;
            svg {
              fill: @accent !important;
            }
          }
        }

        .nav__search {
          border-color: @base;
        }
        .nav__search:hover, .nav__search--active {
          background-color: @base;
          border-color: transparent;
        }
      }

      .modeSwitch .pp_toggle_theme {
        background-color: @base !important;
        box-shadow: inset 0 0 0 1px @surface0 !important;
        .modeSwitch__toggle {
          box-shadow: none;
          background-color: @surface0;
        }
        .modeSwitch__toggle--light-mode::after {
          box-shadow: inset 0 0 0 2px @text, 0 0 0 1px @text;
        }
        .modeSwitch__toggle--dark-mode::after {
          box-shadow: inset 0 0 0 2px @text;
        }
      }

      .browseProducts {
        background-color: @mantle;
        h2 {
          color: @text !important;
        }
        a {
          color: @subtext0 !important;
          &:hover {
            color: @accent;
          }
        }
        .browseProducts__block--group1 .list-unstyled {
          a {
            background-color: @crust !important;
            border-color: @crust !important;
            box-shadow: none;
          }
          a:hover {
            box-shadow: inset 0 0 0 2px @accent;
            background-color: fade(@accent, 15%) !important;
          }
        }
      }
      .navCard--search {
        background-color: @base !important;
        .search_results--link {
          p {
            color: @text;
          }
          &:hover {
            p {
              color: @accent;
            }
          }
          .search_results--category {
            color: @subtext0 !important;
          }
        }
      }

      // Mobile / Small screen width
      .navMobile {
        background-color: @crust;
        .nav__menu--mobile a:hover svg {
          fill: @accent !important;
        }
      }
      .navCard {
        background-color: @base;
        .navCard__header {
          background-color: @crust;
          .navCard__wrapper {
            color: @text !important;
            a:hover svg {
              fill: @accent !important;
            }
          }
        }
        .navCard__content a {
          color: @text;
          &:hover {
            color: @accent;
          }
        }
      }
    }

    // === Footer === //
    footer {
      background-color: @crust;
      .footer {
        border-color: @surface0;
      }
      h2, p {
        color: @text;
        border-color: @surface0;
      }
      .footer__logo--img {
        content: url("data:image/svg+xml,@{logoSmall}");
      }
    }

    // === Homepage === //
    #homepage {
      h1, p {
        color: @text !important;
      }
      .wrapper__intro-2023 {
        background-color: @base !important;
        .intro__info {
          // Mobile only
          background-image: url("data:image/svg+xml,@{logoText}");
          @media only screen and (min-width: 1100px) {
            background-image: none !important;
          }
        }
      }
      .wrapper__buildGuides {
        background-color: @crust;
      }
      .wrapper__completedBuilds {
        background-color: @base;
        .logGroup__card--featured_2023 {
          background-color: @accent;
          .featured__message {
            h1 {
              color: @base !important;
            }
            svg {
              fill: @base !important;
            }
          }
        }
      }
    }

    // === Partlist Editor Page === //
    #partlist {
      .wrapper__pageContent {
        // Notes (various warnings and disclaimers about confitcts and such)
        .note__tag {
          color: @base !important;
        }
        .note__tag--info {
          background-color: @blue;
        }
        .note__text--info span {
          color: @blue;
        }
        .note__tag--warning {
          background-color: @peach;
        }
        .note__text--warning span {
          color: @peach;
        }
        .note__tag--problem {
          background-color: @red;
        }
        .note__text--problem span {
          color: @red;
        }
      }

      .actionBoxGroup {
        background-color: @surface0;
        .actionBox__permalink--copy {
          background-color: @base;
          border-color: @base;
          &:hover svg {
            fill: @accent !important;
          }
        }
        .text-input:hover, .text-input:focus {
          color: @accent !important;
        }
        .actionBox__markup {
          color: @text;
          .actionBox__markupLink:hover svg {
            fill: @accent !important;
          }
        }
        .actionBox__options > li {
          border-color: @mantle;
          a {
            .set-colors(@mantle, @mantle, @text);
            &:hover {
              color: @accent;
              svg {
                fill: @accent !important;
              }
            }
          }
        }
      }

      .partlist__metrics-2023 {
        .partlist__compatibility {
          svg {
            fill: @base !important;
          }
          a, p, span {
            color: @base;
          }
          a:hover {
            color: @crust;
          }
        }
        .partlist__compatibility--noIssues {
          background-color: @green;
        }
        .partlist__compatibility--warning {
          background-color: @peach;
        }
        .partlist__compatibility--notes {
          background-color: @teal;
        }
        .partlist__compatibility--error {
          background-color: @red;
        }
        .partlist__keyMetric {
          background-color: @blue;
          svg {
            fill: @base !important;
          }
          a, p, span {
            color: @base;
          }
        }
      }

      .partlist__promos {
        h6, li {
          color: @text;
        }
      }

      .partlist--totals {
        border-color: @surface1;
      }

      #allocation_container {
        .allocations__component {
          .img__part {
            border-color: transparent;
          }
        }
        .allocation__header, .allocation__port {
          background-color: @crust;
          border-color: transparent;
          box-shadow: none;
          .port__block {
            border-color: @surface0;
            .port__label {
              color: @subtext0;
              span {
                color: @overlay0;
              }
            }
            .port__info {
              background-color: @surface0;
              p {
                color: @text;
              }
            }
          }
          .port__blockSolid--info {
            border-color: @blue;
            &::after {
              background-color: @blue;
            }
            .port__label {
              color: @blue;
            }
          }
          .port__blockSolid--warning {
            border-color: @peach;
            &::after {
              background-color: @peach;
            }
            .port__label {
              color: @peach;
            }
          }
          .port__blockSolid--problem {
            border-color: @red;
            &::after {
              background-color: @red;
            }
            .port__label {
              color: @red;
            }
          }

          .port__blockEmpty--info {
            &::before {
              background-color: transparent;
              box-shadow: inset 0 0 0 2px @blue;
            }
            &::after {
              background: repeating-linear-gradient(
                to right,
                transparent,
                transparent 9px,
                @blue 9px,
                @blue 18px
              );
            }
          }
          .port__blockEmpty--warning {
            &::before {
              background-color: transparent;
              box-shadow: inset 0 0 0 2px @peach;
            }
            &::after {
              background: repeating-linear-gradient(
                to right,
                transparent,
                transparent 9px,
                @peach 9px,
                @peach 18px
              );
            }
          }
          .port__blockEmpty--problem {
            &::before {
              background-color: transparent;
              box-shadow: inset 0 0 0 2px @red;
            }
            &::after {
              background: repeating-linear-gradient(
                to right,
                transparent,
                transparent 9px,
                @red 9px,
                @red 18px
              );
            }
          }
        }
        .allocation__connection {
          .connection__block--info {
            background-color: @blue;
          }
          .connection__block--warning {
            background-color: @peach;
          }
          .connection__block--problem {
            background-color: @red;
          }
        }
        .allocation__part {
          .part__label {
            color: @base;
            a {
              color: @base;
              &:hover {
                color: @surface0;
              }
            }
            span {
              color: @base;
            }
          }
          .part__block--info {
            background-color: @blue;
            border-color: @blue;
          }
          .part__block--warning {
            background-color: @peach;
            border-color: @peach;
          }
          .part__block--problem {
            background-color: @red;
            border-color: @red;
          }
        }
      }

      #price_history {
        .pricing-table-legend {
          .price-history-legend-item {
            color: @text;
            // The colors for the key are randomly generated and the canvas can't be styled so they've been left unstyled
          }
        }
        .price-history-chart {
          div {
            color: @text;
            border-color: @surface0;
          }
        }
      }
    }

    // === Product Selection Page === //
    #products {
      .wrapper__pageContent {
        .sidebar-content .offCanvas__sidebar {
          .miniPartlist-2023 {
            background-color: @surface0;
            .compatibility__wrapper {
              background-color: @base;
              border-color: @base;
              color: @text;
            }
          }
          // Mobile
          .filter-count {
            color: @accent;
          }
        }

        .main-content {
          .productList__cover {
            background-color: @base;
          }
          .productList__actions {
            .productList__actions--left {
              .disabled {
                color: @subtext0 !important;
                &:hover {
                  color: @text !important;
                }
              }
            }
          }
        }
      }
    }

    // === Product Page === //
    #product-page {
      .sidebar-content {
        .actionBoxGroup--product-2023 {
          background-color: @surface0;
          .actionBox-2023 {
            border-color: @overlay0;
          }
        }
        .actionBoxGroup--productSeries {
          a {
            .set-colors(@surface1, @surface1, @text);
            &:hover {
              .set-colors(@accent, @accent, @base);
            }
          }
          .active {
            .set-colors(@accent, @accent, @base);
          }
          .inactive {
            .set-colors(@surface0, @surface0, @text);
            opacity: 1;
            &:hover {
              .set-colors(@surface1, @surface1, @text);
            }
          }
        }
      }
      .partReviews__name {
        color: @subtext0;
      }
      .partReviews__review {
        border-bottom-color: @surface0 !important;
      }
    }

    // === Build Pages ===
    #buildguide-view, #userbuild-view {
      // Part of the buildguide and userbuild pages are a partlist so same selectors are used
      #partlist();

      .thumbnail-active {
        &.active {
          border-color: @accent;
        }
      }
      .actionBox__actions a {
        .set-colors(@mantle, transparent, @text);
        &:hover {
          border-color: @accent;
          color: @accent;
          svg {
            fill: @accent !important;
          }
        }
        &.actionBox__vote--voted svg {
          fill: @accent !important;
        }
      }
    }

    // === Gallery === (Shown when clicking on any product or user image)
    .offCanvas__gallery {
      .gallery__header {
        background-color: @crust;
        border-color: @crust;
        background-image: url("data:image/svg+xml,@{logo}");
        .gallery__title {
          border-color: @crust;
          background-color: @crust;
          h1, h3 {
            color: @text;
          }
        }
        span {
          background-color: @subtext0 !important;
        }
      }
      .gallery__controls {
        .pp-gallery-left:hover, .pp-gallery-right:hover {
          background-color: @mantle;
        }
      }
      .gallery__controls--mobile {
        background-color: @crust;
      }
    }
    .pp_open_gallery {
      &:hover {
        border-color: @accent;
      }
      span {
        background-color: fade(@surface0, 60%);
        color: @text;
      }
    }

    // === Search Results ===
    #search-results {
      .search_results--link a, .product__link {
        color: @text;
        &:hover {
          color: @accent;
        }
      }
      .search_results--img {
        border-color: transparent;
      }
    }

    // === Price Trends ===
    #price-trends {
      .price-trend-card {
        transition-property: box-shadow, background;
        background-color: @surface0;
        h2 {
          color: @text;
        }
        &:hover {
          background-color: @surface1;
          h2 {
            color: @accent;
          }
        }
      }
    }

    // === Account Settings ===
    #user-preferences {
      .sidebar-content .userPref__nav {
        background-color: @mantle;
        border-color: transparent;
        .list-active a {
          background-color: @accent;
          color: @base;
        }
      }
      .tax-rate::after {
        color: @subtext0 !important;
      }
    }

    // === Misc Elements === //

    //==Ratings==//
    .ratingBar .ratingBar__track {
      background-color: @crust !important;
      .ratingBar__bar {
        background-color: @yellow !important;
        &:hover {
          background-color: lighten(@yellow, 5%) !important;
        }
      }
    }
    .icon.shape-star-full, .icon.shape-star-half {
      fill: @yellow !important;
    }
    .icon.shape-star-empty {
      fill: @surface0 !important;
    }

    //==Random Small Elements==//

    // Cookies
    .cc-window {
      background-color: @blue;
      color: @base;
      a {
        color: @mantle !important;
        &:hover {
          color: @crust !important;
        }
      }
      .cc-btn:not(:first-child) {
        background-color: @text;
      }
    }

    // Register / Login
    #register .card, #login .card {
      background-color: @crust !important;
      .checkbox:not(:checked) + label::before {
        background-color: @mantle;
      }
      .note--belowButton {
        border-color: @surface0;
      }
    }

    // Page selection
    #module-pagination {
      .pagination--current {
        background-color: @accent;
        color: @base;
      }
    }

    // Applied Filters
    .appliedFilter {
      .pp-filter-breadcrumb {
        background-color: @accent !important;
        border-color: @accent !important;
        // Normally only transitions border color but we need to also transition background color
        transition-property: all;
        &:hover {
          background-color: @red !important;
          border-color: @red !important;
        }
        .appliedFilter__value {
          color: @base !important;
          svg {
            fill: @base !important;
          }
        }
      }
    }

    // Price Graphs
    .pricing-table {
      .flot-text {
        color: @text !important;
      }
      .price-history-tooltip {
        background-color: @mantle;
        color: @text;
      }
    }

    // Box showing saved part lists. Used in user profile
    .partlist__saved, .userbuild__partlist, #partlist_select_current a {
      background-color: @mantle;
      border-color: @mantle;
    }

    // Image editor for userbuilds
    .productGallery__wrapper {
      background-color: @base !important;
      border-color: @surface0 !important;
    }
    #gallery_box {
      background-color: @base !important;
      border-color: @base !important;
    }
    .image-list li {
      background-color: @crust !important;
      border-color: @surface0 !important;
    }

    // Dragable Lists
    .list-movable.list-active a {
      background-color: @crust !important;
    }

    // Tooltip popups
    .tooltipText {
      color: @base;
      background-color: @accent;
      &::after {
        border-color: @accent transparent transparent transparent;
      }
    }

    // User content
    .ugcActions {
      color: @text;
      .comment-voted-up svg, .comment-vote-up svg:hover {
        fill: @green !important;
      }
      .comment-voted-down svg, .comment-vote-down svg:hover {
        fill: @red !important;
      }
    }
    .comment--nested .comment__wrapper, .comment__wrapper {
      border-color: @surface1;
      .comment {
        border-color: @surface1;
      }
    }
    // Username
    .user a {
      color: @accent !important;
      &:hover {
        color: lighten(@accent, 5%) !important;
      }
    }
    // Various tags that appear next to commenters names
    .userDetails__userModifier {
      background-color: @text;
      span {
        color: @base;
      }
    }
    .comment-modifier-staff svg {
      background-color: @blue;
      fill: @base !important;
    }
    .comment-modifier-submitter svg {
      background-color: @green;
      fill: @base !important;
    }

    // Benchmark Percentile Bars
    .lhs-benchmark, .category-benchmark {
      // Percentage bars that show the percentile of the benchmarked part in specific stats
      background-color: @surface0;
      .lhs-benchmark-inner, .category-benchmark-inner {
        background-color: @accent;
      }
    }

    // Forums Staff Dot
    .topicTitle--staff::before {
      background-color: @red !important;
    }

    // Toasts
    .pageMessage p {
      // Mostly used as confirmation of an action such as copying a permalink through a button
      background-color: @green;
      color: @base;
    }

    // Box with aspect ratio info
    .ratio {
      // Used in wallpapers page at pcpartpicker.com/downloads
      background-color: @accent !important;
      color: @base;
    }

    // Mainly used in forums
    .subTitle {
      border-color: @surface1;
    }
    .group {
      border-color: @surface0 !important;
    }
    .group__title {
      color: @text !important;
    }

    .offCanvas {
      // Sidebars commonly found in user pages
      background-color: @base;
    }

    div[style*="color: red;"] {
      // Only used when uploading a new userbuild and no images attached (as far as I know)
      color: @red !important;
    }

    .row--lastPostTimestamp p {
      // Only appears on small screens
      color: @subtext0 !important;
    }

    .tabsGroup > ul > li.more:hover {
      ul, > a {
        background-color: @surface0 !important;
      }
    }
  }
}

sections.code:
:root.dark-mode {
  color-scheme: dark;
  background-color: #1e1e2e;
}
:root.dark-mode ::selection {
  background-color: rgba(203, 166, 247, 0.3);
}
:root.dark-mode input::placeholder,
:root.dark-mode textarea::placeholder {
  color: #a6adc8 !important;
}
:root.dark-mode body,
:root.dark-mode .wrapper__pageContent {
  color: #cdd6f4;
  background-color: #1e1e2e;
}
:root.dark-mode svg.icon,
:root.dark-mode svg.nav__icon {
  fill: #a6adc8 !important;
}
:root.dark-mode a[href]:not(.button) {
  color: #cba6f7;
}
:root.dark-mode a[href]:not(.button):hover {
  color: #d9bdf9;
}
:root.dark-mode .list-unstyled li {
  color: #cdd6f4;
  border-color: #313244;
}
:root.dark-mode input:not(.button) {
  background-color: #181825;
  border-color: #181825;
  color: #cdd6f4;
  box-shadow: none;
}
:root.dark-mode .wrapper-formField label {
  color: #cdd6f4;
}
:root.dark-mode select {
  background-color: #181825;
  color: #cdd6f4;
  background-image: url("data:image/svg+xml,%3Csvg%20version%3D%221.1%22%20xmlns%3D%22http%3A//www.w3.org/2000/svg%22%20xmlns%3Axlink%3D%22http%3A//www.w3.org/1999/xlink%22%20x%3D%220px%22%20y%3D%220px%22%20viewBox%3D%220%200%2018%2018%22%20enable-background%3D%22new%200%200%2018%2018%22%20xml%3Aspace%3D%22preserve%22%3E%3Cpolygon%20points%3D%229,13.6%202.2,6.8%203.8,5.2%209,10.4%2014.2,5.2%2015.8,6.8%22%20fill%3D%22%23cdd6f4%22/%3E%3C/svg%3E") !important;
  box-shadow: none;
}
:root.dark-mode textarea {
  background-color: #181825;
  box-shadow: none;
}
:root.dark-mode .button {
  background-color: #cba6f7;
  border-color: #cba6f7;
  color: #1e1e2e;
}
:root.dark-mode .button svg {
  fill: #1e1e2e !important;
}
:root.dark-mode .button.button--negative {
  background-color: #f38ba8;
  border-color: #f38ba8;
  color: #1e1e2e;
}
:root.dark-mode .button.button--success {
  background-color: #a6e3a1;
  border-color: #a6e3a1;
  color: #1e1e2e;
}
:root.dark-mode .button.button--dark {
  background-color: #1e1e2e;
  border-color: #1e1e2e;
  color: #cdd6f4;
}
:root.dark-mode .button.button--dark svg {
  fill: #cdd6f4 !important;
}
:root.dark-mode .button:not(.button--disabled):not(:disabled):hover {
  background-color: #d9bdf9;
  border-color: #d9bdf9;
  color: #1e1e2e;
}
:root.dark-mode .button:not(.button--disabled):not(:disabled):hover.button--negative {
  background-color: #f5a2b9;
  border-color: #f5a2b9;
  color: #1e1e2e;
}
:root.dark-mode .button:not(.button--disabled):not(:disabled):hover.button--success {
  background-color: #b9e9b5;
  border-color: #b9e9b5;
  color: #1e1e2e;
}
:root.dark-mode .button:not(.button--disabled):not(:disabled):hover.button--dark {
  background-color: #181825;
  border-color: #181825;
  color: #cdd6f4;
}
